# normalized component shape and containment in larger component, no rotation

def norm(cells):
 mr=min(r for r,c in cells); mc=min(c for r,c in cells); return frozenset((r-mr,c-mc) for r,c in cells)
def embeds(small,large):
 sh=norm(small); lh=set(large)
 h=max(r for r,c in sh)+1; w=max(c for r,c in sh)+1
 lr=max(r for r,c in lh); lc=max(c for r,c in lh)
 for dr in range(lr-h+2):
  for dc in range(lc-w+2):
